#include <assert.h>
#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define NAME_SIZE 40
struct Contact { int id; char name[NAME_SIZE]; char phone[24]; };

static int compare_name_text(const char *a,const char *b) {
    while(*a!='\0'&&*b!='\0'){
        int ca=tolower((unsigned char)*a),cb=tolower((unsigned char)*b);
        if(ca<cb)return -1;
        if(ca>cb)return 1;
        ++a;++b;
    }
    if(*a=='\0'&&*b=='\0')return 0;
    return *a=='\0'?-1:1;
}
static int compare_contacts(const void *left,const void *right) {
    const struct Contact *a=left,*b=right;
    int by_name=compare_name_text(a->name,b->name);
    if(by_name!=0)return by_name;
    return (a->id>b->id)-(a->id<b->id);
}
static size_t lower_bound_name(const struct Contact *items,size_t count,const char *key) {
    size_t low=0U,high=count;
    while(low<high){
        size_t mid=low+(high-low)/2U;
        if(compare_name_text(items[mid].name,key)<0)low=mid+1U;
        else high=mid;
    }
    return low;
}
static size_t find_id(const struct Contact *items,size_t count,int id) {
    size_t i;for(i=0;i<count;++i)if(items[i].id==id)return i;return count;
}
int main(void) {
    struct Contact contacts[]={{3,"Mira","9000000003"},{1,"asha","9000000001"},{4,"Asha","9000000004"},{2,"Zoya","9000000002"}};
    const size_t count=sizeof contacts/sizeof contacts[0];
    size_t i,at,matches=0U;
    qsort(contacts,count,sizeof contacts[0],compare_contacts);
    assert(strcmp(contacts[0].name,"asha")==0);
    assert(strcmp(contacts[1].name,"Asha")==0);
    assert(strcmp(contacts[3].name,"Zoya")==0);
    at=lower_bound_name(contacts,count,"ASHA");
    while(at+matches<count&&compare_name_text(contacts[at+matches].name,"asha")==0)++matches;
    assert(matches==2U);
    assert(find_id(contacts,count,3)==2U);
    assert(find_id(contacts,count,99)==count);
    for(i=0;i<count;++i)printf("%d | %s | %s\n",contacts[i].id,contacts[i].name,contacts[i].phone);
    printf("Case-insensitive matches for Asha: %zu\n",matches);
    puts("Sorting and binary-search tests passed.");
    return 0;
}

#include <ctype.h>
#include <limits.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define NAME_SIZE 40
#define PHONE_SIZE 24
#define INPUT_SIZE 128
struct Contact { int id; char name[NAME_SIZE]; char phone[PHONE_SIZE]; };
struct AddressBook { struct Contact *items; size_t count; size_t capacity; };

static char *trim(char *s) {
    char *start=s,*end;
    while(isspace((unsigned char)*start))++start;
    end=start+strlen(start);
    while(end>start&&isspace((unsigned char)end[-1]))--end;
    *end='\0';return start;
}
static int read_line(const char *prompt,char *buf,size_t size) {
    size_t n;int ch;fputs(prompt,stdout);
    if(fgets(buf,(int)size,stdin)==NULL)return 0;
    n=strlen(buf);
    if(n>0U&&buf[n-1U]=='\n'){buf[n-1U]='\0';return 1;}
    ch=getchar();if(ch=='\n'||ch==EOF)return 1;
    while(ch!='\n'&&ch!=EOF)ch=getchar();
    return -1;
}
static int read_int(const char *prompt,int min,int max,int *out) {
    char line[INPUT_SIZE],*s,*end;long value;int r=read_line(prompt,line,sizeof line);
    if(r!=1)return r;
    s=trim(line);value=strtol(s,&end,10);
    while(isspace((unsigned char)*end))++end;
    if(s==end||*end!='\0'||value<min||value>max)return -1;
    *out=(int)value;return 1;
}
static int compare_name_text(const char *a,const char *b) {
    while(*a!='\0'&&*b!='\0'){
        int ca=tolower((unsigned char)*a),cb=tolower((unsigned char)*b);
        if(ca<cb)return -1;
        if(ca>cb)return 1;
        ++a;++b;
    }
    if(*a=='\0'&&*b=='\0')return 0;
    return *a=='\0'?-1:1;
}
static int compare_contacts(const void *left,const void *right) {
    const struct Contact *a=left,*b=right;
    int c=compare_name_text(a->name,b->name);
    if(c!=0)return c;
    return (a->id>b->id)-(a->id<b->id);
}
static size_t lower_bound_name(const struct Contact *items,size_t count,const char *key) {
    size_t low=0U,high=count;
    while(low<high){size_t mid=low+(high-low)/2U;
        if(compare_name_text(items[mid].name,key)<0)low=mid+1U;else high=mid;
    }return low;
}
static size_t find_id(const struct AddressBook *book,int id) {
    size_t i;for(i=0;i<book->count;++i)if(book->items[i].id==id)return i;return book->count;
}
static int reserve_contacts(struct AddressBook *book,size_t needed) {
    size_t cap;struct Contact *tmp;
    if(needed<=book->capacity)return 1;
    if(needed>SIZE_MAX/sizeof *book->items)return 0;
    cap=book->capacity==0U?4U:book->capacity;
    while(cap<needed){if(cap>SIZE_MAX/2U){cap=needed;break;}cap*=2U;}
    if(cap>SIZE_MAX/sizeof *book->items)return 0;
    tmp=realloc(book->items,cap*sizeof *book->items);
    if(tmp==NULL)return 0;
    book->items=tmp;book->capacity=cap;return 1;
}
static int add_contact(struct AddressBook *book,const struct Contact *contact) {
    if(contact->id<=0||contact->name[0]=='\0'||strlen(contact->name)>=NAME_SIZE
       ||contact->phone[0]=='\0'||strlen(contact->phone)>=PHONE_SIZE
       ||find_id(book,contact->id)!=book->count||book->count==SIZE_MAX)return 0;
    if(!reserve_contacts(book,book->count+1U))return 0;
    book->items[book->count++]=*contact;return 1;
}
static void add_menu(struct AddressBook *book) {
    struct Contact c;char line[INPUT_SIZE],*s;size_t n;int r;
    r=read_int("Contact ID: ",1,INT_MAX,&c.id);
    if(r!=1){puts(r==0?"Input ended.":"Invalid ID.");return;}
    if(find_id(book,c.id)!=book->count){puts("That ID already exists.");return;}
    r=read_line("Name: ",line,sizeof line);
    if(r!=1){puts(r==0?"Input ended.":"Name is too long.");return;}
    s=trim(line);n=strlen(s);
    if(n==0U||n>=NAME_SIZE||strchr(s,'|')!=NULL){puts("Enter a name of 1 to 39 characters.");return;}
    memcpy(c.name,s,n+1U);
    r=read_line("Phone (digits and optional leading +): ",line,sizeof line);
    if(r!=1){puts(r==0?"Input ended.":"Phone is too long.");return;}
    s=trim(line);n=strlen(s);
    if(n==0U||n>=PHONE_SIZE||strchr(s,'|')!=NULL){puts("Enter a phone value of 1 to 23 characters.");return;}
    {size_t i;for(i=0;i<n;++i)if(!(isdigit((unsigned char)s[i])||(i==0U&&s[i]=='+'))){puts("Phone must contain digits and an optional leading +.");return;}}
    memcpy(c.phone,s,n+1U);
    if(!add_contact(book,&c))puts("Could not add contact (memory or validation failure).");
    else puts("Contact added.");
}
static void list_contacts(struct AddressBook *book) {
    size_t i;if(book->count==0U){puts("Address book is empty.");return;}
    if(book->count>1U)qsort(book->items,book->count,sizeof book->items[0],compare_contacts);
    puts("\nID     NAME                                     PHONE");
    for(i=0;i<book->count;++i)printf("%-6d %-40s %s\n",book->items[i].id,book->items[i].name,book->items[i].phone);
}
static void search_contacts(struct AddressBook *book) {
    char key[INPUT_SIZE],*s;size_t at,matches=0U,n;int r;
    r=read_line("Name to search (case-insensitive): ",key,sizeof key);
    if(r!=1){puts(r==0?"Input ended.":"Search text is too long.");return;}
    s=trim(key);n=strlen(s);if(n==0U){puts("Enter a name.");return;}
    if(book->count>1U)qsort(book->items,book->count,sizeof book->items[0],compare_contacts);
    at=lower_bound_name(book->items,book->count,s);
    while(at+matches<book->count&&compare_name_text(book->items[at+matches].name,s)==0)++matches;
    if(matches==0U){puts("No matching contact.");return;}
    printf("%zu matching contact(s):\n",matches);
    while(matches>0U){const struct Contact *c=&book->items[at++];
        printf("%d | %s | %s\n",c->id,c->name,c->phone);--matches;
    }
}
int main(void) {
    struct AddressBook book={NULL,0U,0U};int done=0;
    while(!done){
        int choice,r;
        puts("\nMINI ADDRESS BOOK");
        puts("1 Add contact  2 List sorted  3 Search by name  0 Exit");
        r=read_int("Choose: ",0,3,&choice);
        if(r==0){puts("\nEnd of input.");break;}
        if(r<0){puts("Choose 0, 1, 2 or 3.");continue;}
        switch(choice){
            case 1:add_menu(&book);break;
            case 2:list_contacts(&book);break;
            case 3:search_contacts(&book);break;
            case 0:done=1;break;
            default:break;
        }
    }
    free(book.items);book.items=NULL;book.count=0U;book.capacity=0U;
    puts("Address book memory released. Goodbye.");return 0;
}
